class TicTacToe:
    BOARD_SIZE = 3
    EMPTY_CELL = ' '
    PLAYER_X = 'X'
    PLAYER_O = 'O'

    def __init__(self, N=3):
        self.board = [[self.EMPTY_CELL for _ in range(N)] for _ in range(3)]
        self.current_player = self.PLAYER_X

    def make_move(self, row, col):
        if self._is_valid_move(row, col):
            self._place_piece(row, col)
            self._switch_player()
            return True
        return False

    def _is_valid_move(self, row, col):
        return self.board[row][col] == self.EMPTY_CELL

    def _place_piece(self, row, col):
        self.board[row][col] = self.current_player

    def _switch_player(self):
        self.current_player = self.PLAYER_O if self.current_player == self.PLAYER_X else self.PLAYER_X

    def check_winner(self):
        winner = self._check_rows()
        if winner:
            return winner
        winner = self._check_columns()
        if winner:
            return winner
        winner = self._check_diagonals()
        if winner:
            return winner
        return None

    def _check_rows(self):
        for row in self.board:
            if self._is_all_same_non_empty(row):
                return row[0]
        return None

    def _check_columns(self):
        for col in range(3):
            column = [self.board[row][col] for row in range(3)]
            if self._is_all_same_non_empty(column):
                return column[0]
        return None

    def _check_diagonals(self):
        main_diagonal = [self.board[0][0], self.board[1][1], self.board[2][2]]
        if self._is_all_same_non_empty(main_diagonal):
            return main_diagonal[0]
        anti_diagonal = [self.board[0][2], self.board[1][1], self.board[2][0]]
        if self._is_all_same_non_empty(anti_diagonal):
            return anti_diagonal[0]
        return None

    def _is_all_same_non_empty(self, line):
        return len(set(line)) == 1 and line[0] != self.EMPTY_CELL

    def is_board_full(self):
        for row in self.board:
            if self.EMPTY_CELL in row:
                return False
        return True
